<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { apiClient } from '../../../shared/api'
import PageHeader from '../../../shared/components/PageHeader.vue'
import { describeApiFailure } from '../../../shared/utils/errorMessage'
import { addManualLiveSegment, analyzeLiveSegment, correctLiveSegmentRole, createLiveInterviewSession, endLiveInterviewSession, findActiveLiveInterviewSession, generateInterviewQuestions, getInterview, updateLiveInterviewQuestion, uploadLiveInterviewChunk, type ApiInterviewDetail, type GeneratedInterviewQuestion, type LiveAnswerAnalysis, type LiveInterviewSegment } from '../api'
import { buildUtterances } from '../utils/utterance-state'
import { createAnalysisRetryState } from '../utils/analysis-retry-state'

const route = useRoute()
const router = useRouter()
const detail = ref<ApiInterviewDetail | null>(null)
const candidateName = ref('')
const jobTitle = ref('')
const loading = ref(true)
const error = ref('')
const sessionId = ref('')
const status = ref<'idle' | 'starting' | 'recording' | 'paused' | 'manual' | 'stopping' | 'failed'>('idle')
const segments = ref<LiveInterviewSegment[]>([])
const currentQuestion = ref('请先做一下自我介绍，并重点说明与你应聘岗位相关的经历。')
const generatedQuestions = ref<GeneratedInterviewQuestion[]>([])
const generatingQuestions = ref(false)
const questionEngine = ref<'llm' | 'local_fallback' | ''>('')
const microphoneState = ref<'unknown' | 'unsupported' | 'prompt' | 'ready' | 'denied' | 'not-found' | 'busy' | 'error'>('unknown')
const microphoneLabel = ref('未检测')
const audioInputCount = ref(0)
const analyses = ref<Record<string, LiveAnswerAnalysis>>({})
const analyzingId = ref('')
const manualText = ref('')
const manualRole = ref<'candidate' | 'interviewer'>('candidate')
const elapsedSeconds = ref(0)
const recordingNowMs = ref(0)
const analysisRetryState = createAnalysisRetryState()
const analysisRetryTick = ref(0)
const externalServices = ref<Record<string, string>>({})
const funasrAvailable = computed(() => externalServices.value.funasr === 'ok')
const externalServiceWarning = computed(() => { const unavailable = Object.entries(externalServices.value).filter(([, value]) => value === 'unavailable').map(([key]) => key); if (!unavailable.length) return ''; if (unavailable.length === 1 && unavailable[0] === 'funasr') return '外部服务提示：语音转写服务不可用或未配置，已切换为手动记录回答；AI 回答分析仍可用。'; const labels: Record<string, string> = { funasr: '语音转写', llm: 'AI 回答分析', ocr: '简历 OCR 解析' }; return `外部服务提示：${unavailable.map((key) => labels[key] ?? key).join('、')}不可用或未配置，相关功能不可用。` })
let recorder: MediaRecorder | undefined
let timer: ReturnType<typeof setInterval> | undefined
let recordingStartedAt = 0
let lastChunkEndedAt = 0
let analysisRetryTimer: ReturnType<typeof setTimeout> | undefined
const ANSWER_SILENCE_MS = 1600

const elapsed = computed(() => `${String(Math.floor(elapsedSeconds.value / 60)).padStart(2, '0')}:${String(elapsedSeconds.value % 60).padStart(2, '0')}`)
const latestAnalysis = computed(() => { const values=Object.values(analyses.value); return values[values.length - 1] })
const utterances = computed(() => buildUtterances(segments.value, recordingNowMs.value, ANSWER_SILENCE_MS))
const statusLabel = computed(() => ({ idle: '尚未开始', starting: '正在启动', recording: '正在录音', paused: '录音已暂停', manual: '手动记录中', stopping: '正在保存', failed: '服务异常' })[status.value])
const microphoneStatusLabel = computed(() => ({
  unknown: '未检测',
  unsupported: '浏览器不支持麦克风',
  prompt: '等待麦克风授权',
  ready: audioInputCount.value ? `已检测到 ${audioInputCount.value} 个麦克风` : '麦克风可用',
  denied: '麦克风权限被拒绝',
  'not-found': '未检测到麦克风',
  busy: '麦克风被占用',
  error: '麦克风检测异常',
})[microphoneState.value])

function toBase64(blob: Blob): Promise<string> { return new Promise((resolve, reject) => { const reader=new FileReader(); reader.onloadend=()=>resolve(String(reader.result).split(',')[1] || ''); reader.onerror=()=>reject(reader.error || new Error('读取录音片段失败')); reader.readAsDataURL(blob) }) }
function formatTimestamp(ms: number): string { const total=Math.max(0,Math.round(ms/1000)); return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}` }
function microphoneErrorState(error: unknown): typeof microphoneState.value { const name=(error as {name?:string})?.name; if(name==='NotAllowedError'||name==='PermissionDeniedError'||name==='SecurityError')return 'denied'; if(name==='NotFoundError'||name==='DevicesNotFoundError')return 'not-found'; if(name==='NotReadableError'||name==='TrackStartError')return 'busy'; return 'error' }
async function refreshMicrophoneState(requestPermission=false){ if(!navigator.mediaDevices?.enumerateDevices){microphoneState.value='unsupported';microphoneLabel.value='浏览器不支持麦克风检测';return} try { if(requestPermission){const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach((track)=>track.stop())} const devices=await navigator.mediaDevices.enumerateDevices(); const inputs=devices.filter((device)=>device.kind==='audioinput'); audioInputCount.value=inputs.length; microphoneLabel.value=inputs.map((item)=>item.label).filter(Boolean)[0] || (inputs.length?'默认麦克风':'未检测到设备'); if(!inputs.length){microphoneState.value='not-found';return} if(!requestPermission){const permission=await navigator.permissions?.query({name:'microphone' as PermissionName}).catch(()=>undefined); if(permission?.state==='denied'){microphoneState.value='denied';return} if(permission?.state==='prompt'){microphoneState.value='prompt';return}} microphoneState.value='ready' } catch(error){microphoneState.value=microphoneErrorState(error);microphoneLabel.value=error instanceof Error?error.message:'麦克风检测失败'} }
function onMicrophoneDeviceChange(){void refreshMicrophoneState(false)}
async function generateResumeQuestions(){ if(!detail.value || generatingQuestions.value)return; generatingQuestions.value=true; error.value=''; try { const result=await generateInterviewQuestions(detail.value.id,5); generatedQuestions.value=result.questions;questionEngine.value=result.engine; if(!currentQuestion.value.trim() && result.questions[0]) currentQuestion.value=result.questions[0].question } catch(cause){error.value=describeApiFailure(cause,'根据简历生成题目失败').message} finally {generatingQuestions.value=false} }
async function adoptQuestion(question:GeneratedInterviewQuestion){ currentQuestion.value=question.question; if(sessionId.value) await saveQuestion('ai_adopted') }
 async function load() { loading.value=true; try { const id=String(route.params.id ?? ''); detail.value=await getInterview(id); const [candidates,jobs,active]=await Promise.all([apiClient.getJson<Array<{id:string;fullName:string}>>('/candidates'),apiClient.getJson<Array<{id:string;title:string}>>('/jobs'),findActiveLiveInterviewSession(id)]); candidateName.value=candidates.data.find((item)=>item.id===detail.value?.application.candidateId)?.fullName || detail.value.application.candidateId; jobTitle.value=jobs.data.find((item)=>item.id===detail.value?.application.jobId)?.title || detail.value.application.jobId; if(active){sessionId.value=active.session.id;currentQuestion.value=active.session.currentQuestion;segments.value=active.segments;active.segments.forEach((item)=>{if(item.analysis){analyses.value={...analyses.value,[item.id]:item.analysis!};analysisRetryState.restore(item.id)}});recordingNowMs.value=Math.max(0,...active.segments.map((item)=>item.endMs))+ANSWER_SILENCE_MS;status.value='paused'} apiClient.getJson<any>('/ready').then((res)=>{externalServices.value=res.data?.checks?.externalServices??{};if(status.value==='paused'&&!funasrAvailable.value)status.value='manual'}).catch(()=>{}); void generateResumeQuestions(); void refreshMicrophoneState(false) } catch(cause) { error.value=describeApiFailure(cause,'读取面试信息失败').message } finally { loading.value=false } }
async function startManual() { if(!detail.value || status.value==='starting' || status.value==='manual')return; error.value=''; status.value='starting'; try { if(!sessionId.value){const session=await createLiveInterviewSession(detail.value.id);sessionId.value=session.id; if(currentQuestion.value.trim()) await updateLiveInterviewQuestion(session.id,currentQuestion.value.trim(),'manual')} status.value='manual'; if(!timer) timer=setInterval(()=>{elapsedSeconds.value++;recordingNowMs.value=Math.max(recordingNowMs.value,elapsedSeconds.value*1000)},1000) } catch(cause) { error.value=describeApiFailure(cause,'启动手动面试失败').message; status.value='failed' } }
async function addManualSegment() { const text=manualText.value.trim(); if(!sessionId.value || !text)return; try { const startMs=recordingNowMs.value; const segment=await addManualLiveSegment(sessionId.value,text,manualRole.value,startMs,startMs); segments.value.push(segment); recordingNowMs.value=segment.endMs+ANSWER_SILENCE_MS; manualText.value='' } catch(cause) { error.value=describeApiFailure(cause,'添加发言失败').message } }
async function start() { if(!detail.value || status.value==='starting' || status.value==='recording')return; error.value=''; status.value='starting'; try { if(!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder)throw new Error('当前浏览器不支持麦克风录音'); const stream=await navigator.mediaDevices.getUserMedia({audio:true}); microphoneState.value='ready'; audioInputCount.value=Math.max(1,audioInputCount.value); if(!sessionId.value){const session=await createLiveInterviewSession(detail.value.id);sessionId.value=session.id; if(currentQuestion.value.trim()) await updateLiveInterviewQuestion(session.id,currentQuestion.value.trim(),'manual')} recorder=new MediaRecorder(stream); recordingStartedAt=performance.now()-recordingNowMs.value; lastChunkEndedAt=recordingNowMs.value; recorder.ondataavailable=async(event)=>{ if(!event.data.size || !sessionId.value)return; const chunkEndedAt=Math.round(performance.now()-recordingStartedAt); const chunkOffsetMs=lastChunkEndedAt; lastChunkEndedAt=chunkEndedAt; recordingNowMs.value=chunkEndedAt; try { segments.value.push(...await uploadLiveInterviewChunk(sessionId.value,await toBase64(event.data),event.data.type || 'audio/webm',chunkOffsetMs)) } catch(cause) { const failure=describeApiFailure(cause,'语音转写失败'); if(failure.code?.startsWith('FUNASR_')) { externalServices.value={...externalServices.value,funasr:'unavailable'}; if(recorder&&recorder.state!=='inactive')recorder.stop(); if(timer)clearInterval(timer); status.value='manual'; error.value='语音转写服务不可用，已切换为手动记录。请恢复 FunASR 服务后重新开始录音。' } else { error.value=failure.message; status.value='failed' } } }; recorder.onstop=()=>stream.getTracks().forEach((track)=>track.stop()); recorder.start(1000); timer=setInterval(()=>{elapsedSeconds.value++;recordingNowMs.value=Math.round(performance.now()-recordingStartedAt)},1000); status.value='recording' } catch(cause) { const name=(cause as {name?:string})?.name; microphoneState.value=microphoneErrorState(cause); if(name==='NotAllowedError'||name==='PermissionDeniedError'||name==='SecurityError')error.value='麦克风权限被拒绝：请在浏览器地址栏允许麦克风权限后，重新点击「开始面试」'; else if(name==='NotFoundError'||name==='DevicesNotFoundError')error.value='未检测到麦克风设备：请连接麦克风或检查系统录音设备后重试'; else if(name==='NotReadableError'||name==='TrackStartError')error.value='麦克风被其他应用占用：请关闭占用麦克风的应用后重试'; else if(name==='OverconstrainedError')error.value='麦克风不满足录音要求：请更换可用麦克风后重试'; else error.value=cause instanceof Error?`无法启动录音：${cause.message}`:'无法启动 AI 面试'; status.value='failed' } }
async function togglePause() { if(recorder?.state==='recording'){recorder.pause();status.value='paused';return} if(recorder?.state==='paused'){recorder.resume();status.value='recording';return} if(status.value==='paused'){await start()} }
async function stop() { if(!sessionId.value)return; status.value='stopping'; if(recorder && recorder.state!=='inactive')recorder.stop(); if(timer)clearInterval(timer); try { await endLiveInterviewSession(sessionId.value); status.value='idle' } catch(cause) { error.value=describeApiFailure(cause,'保存面试会话失败').message; status.value='failed' } }
async function setRole(segment:LiveInterviewSegment & {sourceIds?:string[]},role:'interviewer'|'candidate'){ try { const updated=await correctLiveSegmentRole(segment.id,role,segment.sourceIds??[segment.id]); updated.forEach((item)=>{const existing=segments.value.find((row)=>row.id===item.id);if(existing)Object.assign(existing,item)}) } catch(cause) { error.value=describeApiFailure(cause,'修正说话人失败').message } }
async function analyze(segment:LiveInterviewSegment & {sourceIds?:string[]}){ if(!currentQuestion.value.trim() || analyzingId.value)return false; analyzingId.value=segment.id; error.value=''; try { const priorContext=utterances.value.filter((row)=>row.final&&row.text.trim()).slice(-8).map((row)=>`${row.role==='candidate'?'候选人':row.role==='interviewer'?'面试官':'待确认'}：${row.text.trim()}`); const result=await analyzeLiveSegment(segment.id,currentQuestion.value.trim(),segment.sourceIds ?? [segment.id],priorContext); analyses.value={...analyses.value,[segment.id]:result}; currentQuestion.value=result.nextQuestion; if(sessionId.value&&result.nextQuestion.trim()) await updateLiveInterviewQuestion(sessionId.value,result.nextQuestion.trim(),'ai_adopted',segment.id); return true } catch(cause) { error.value=describeApiFailure(cause,'回答分析失败').message; return false } finally { analyzingId.value='' } }
async function saveQuestion(source:'manual'|'ai_adopted'='manual'){ if(!sessionId.value||!currentQuestion.value.trim())return; try { const session=await updateLiveInterviewQuestion(sessionId.value,currentQuestion.value.trim(),source); currentQuestion.value=session.currentQuestion } catch(cause) { error.value=describeApiFailure(cause,'保存当前问题失败').message } }
watch([utterances,analysisRetryTick],([rows])=>{ if(analyzingId.value)return; const candidate=rows.find((row)=>row.final&&row.role==='candidate'&&row.confidence>=.6&&analysisRetryState.claim(row.id)); if(!candidate)return; void analyze(candidate).then((saved)=>{if(saved)analysisRetryState.succeed(candidate.id);else {analysisRetryState.fail(candidate.id);analysisRetryTimer=setTimeout(()=>{analysisRetryTick.value++},2000)}}) },{deep:true})
onMounted(async()=>{await load();void refreshMicrophoneState(false);navigator.mediaDevices?.addEventListener?.('devicechange',onMicrophoneDeviceChange)})
onUnmounted(()=>{if(timer)clearInterval(timer);if(analysisRetryTimer)clearTimeout(analysisRetryTimer);if(recorder&&recorder.state!=='inactive')recorder.stop();navigator.mediaDevices?.removeEventListener?.('devicechange',onMicrophoneDeviceChange)})
</script>

<template>
  <div class="page live-page">
    <PageHeader title="AI 面试室" :description="`${candidateName || '候选人'} · ${jobTitle || '岗位加载中'}`">
      <button class="btn btn-ghost" type="button" @click="router.push(`/interviews/${route.params.id}`)">返回面试详情</button>
    </PageHeader>
    <div v-if="loading" class="loading-note">正在准备面试室...</div>
    <div v-else-if="!detail" class="error-note" role="alert">{{ error || '无法读取面试信息' }}</div>
    <template v-else>
      <div class="session-bar">
        <div><span class="record-dot" :class="{ active: status === 'recording' || status === 'manual' }"></span><strong>{{ statusLabel }}</strong><span>{{ elapsed }}</span></div>
        <div class="microphone-status">
          <span class="microphone-dot" :class="`state-${microphoneState}`"></span>
          <span>麦克风：{{ microphoneStatusLabel }}</span>
          <button
            class="btn btn-ghost btn-sm"
            type="button"
            :disabled="microphoneState === 'unsupported'"
            @click="refreshMicrophoneState(true)"
          >
            检查麦克风
          </button>
        </div>
        <div class="inline-actions"><button v-if="status === 'idle' || status === 'failed'" class="btn btn-primary" type="button" @click="funasrAvailable ? start() : startManual()">{{ funasrAvailable ? '开始面试' : '开始面试（手动记录）' }}</button><button v-if="status === 'recording' || (status === 'paused' && funasrAvailable)" class="btn btn-ghost" type="button" @click="togglePause">{{ status === 'paused' ? '继续' : '暂停' }}</button><button v-if="status === 'recording' || status === 'paused' || status === 'manual'" class="btn btn-ghost" type="button" @click="stop">结束面试</button></div>
      </div>
      <div v-if="error" class="error-note" role="alert">{{ error }}</div>
      <div v-if="externalServiceWarning" class="list-muted" role="note" style="padding:8px 12px;border:1px solid var(--border);background:#fff;margin-bottom:10px">{{ externalServiceWarning }}</div>
      <main class="interview-room">
        <section class="room-panel question-panel"><header><span>当前问题</span><small>面试官可修改后提问</small></header><textarea v-model="currentQuestion" rows="7" /><div class="question-actions"><button class="btn btn-ghost" type="button" :disabled="!sessionId" @click="saveQuestion()">保存问题</button><button class="btn btn-ghost" type="button" :disabled="generatingQuestions" @click="generateResumeQuestions">{{ generatingQuestions ? '生成中...' : '根据简历出题' }}</button></div><div v-if="generatedQuestions.length" class="generated-questions"><div class="generated-head"><strong>简历出题</strong><small>共 {{ generatedQuestions.length }} 道 · {{ questionEngine === 'llm' ? '大模型生成' : questionEngine === 'local_fallback' ? '本地暂用' : '' }}</small></div><div class="generated-list"><article v-for="(question, index) in generatedQuestions" :key="question.question"><div class="question-number">第 {{ index + 1 }} 题</div><p>{{ question.question }}</p><small>{{ question.rationale }}</small><button class="btn btn-ghost btn-sm" type="button" @click="adoptQuestion(question)">采用</button></article></div></div><div v-if="latestAnalysis" class="next-question"><span>AI 推荐追问</span><p>{{ latestAnalysis.nextQuestion }}</p><button class="btn btn-primary" type="button" @click="currentQuestion=latestAnalysis.nextQuestion;saveQuestion('ai_adopted')">采用该问题</button></div><div class="consent-note">开始录音前，请确认候选人已知悉并同意录音与 AI 辅助分析。</div></section>
        <section class="room-panel transcript-panel"><header><span>实时转写</span><small>{{ utterances.length }} 轮发言</small></header><div v-if="status === 'manual'" class="manual-entry"><select v-model="manualRole"><option value="candidate">候选人回答</option><option value="interviewer">面试官提问</option></select><textarea v-model="manualText" rows="3" placeholder="输入本轮发言内容" /><button class="btn btn-primary btn-sm" type="button" :disabled="!manualText.trim()" @click="addManualSegment">添加发言</button></div><div v-if="!utterances.length" class="room-empty">{{ funasrAvailable ? '面试开始后，系统会根据说话人和停顿合并完整发言，不会把网络传输包显示成回答。' : '当前未配置语音转写。开始面试后可手动记录候选人和面试官的发言，系统仍会调用大模型分析回答并生成追问。' }}</div><div v-else class="transcript-list"><article v-for="segment in utterances" :key="segment.id" class="utterance" :data-role="segment.role"><div class="utterance-head"><strong>{{ segment.role==='candidate'?'候选人':segment.role==='interviewer'?'面试官':'待确认' }}</strong><small>{{ formatTimestamp(segment.startMs) }}–{{ formatTimestamp(segment.endMs) }} · {{ segment.final?'发言已结束':'正在继续...' }} · {{ Math.round(segment.confidence*100) }}%</small></div><p>{{ segment.text }}</p><div class="utterance-actions"><button type="button" title="标记为面试官" @click="setRole(segment,'interviewer')">面试官</button><button type="button" title="标记为候选人" @click="setRole(segment,'candidate')">候选人</button><button v-if="segment.final && segment.role==='candidate' && segment.confidence>=.6" class="analyze-button" type="button" :disabled="!!analyzingId" @click="analyze(segment)">{{ analyzingId===segment.id?'分析中...':'分析完整回答' }}</button></div></article></div></section>
        <section class="room-panel analysis-panel"><header><span>回答分析</span><small>仅供面试官参考</small></header><div v-if="!latestAnalysis" class="room-empty">确认候选人的回答片段后，可以生成有证据的分析和下一题。</div><template v-else><div class="confidence"><span>分析置信度</span><strong>{{ Math.round(latestAnalysis.confidence*100) }}%</strong></div><p class="analysis-summary">{{ latestAnalysis.summary }}</p><div class="score-list"><div v-for="score in latestAnalysis.scores" :key="score.dimension"><span>{{ score.dimension }}</span><strong>{{ score.score }}/10</strong><small>{{ score.rationale }}</small></div></div><div class="analysis-block"><strong>回答证据</strong><p>{{ latestAnalysis.evidence.join('；') || '未提取到明确证据' }}</p></div><div class="analysis-block"><strong>需要核实</strong><p>{{ latestAnalysis.concerns.join('；') || '暂未发现' }}</p></div></template></section>
      </main>
    </template>
  </div>
</template>

<style scoped>
.live-page{max-width:none}.session-bar{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:10px 14px;border:1px solid var(--border);background:#fff}.session-bar>div{display:flex;align-items:center;gap:10px}.record-dot{width:9px;height:9px;border-radius:50%;background:#94a3b8}.record-dot.active{background:#dc2626;box-shadow:0 0 0 4px #fee2e2}.microphone-status{color:#475569;font-size:12px}.microphone-dot{width:8px;height:8px;border-radius:50%;background:#94a3b8}.microphone-dot.state-ready{background:#16a34a}.microphone-dot.state-prompt{background:#d97706}.microphone-dot.state-denied,.microphone-dot.state-busy,.microphone-dot.state-error{background:#dc2626}.btn-sm{padding:4px 8px;font-size:11.5px}.interview-room{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(360px,1.4fr) minmax(280px,1fr);gap:12px;min-height:620px}.room-panel{min-width:0;border:1px solid var(--border);background:#fff;display:flex;flex-direction:column}.room-panel>header{display:flex;justify-content:space-between;gap:10px;padding:13px 14px;border-bottom:1px solid var(--border);font-weight:700}.room-panel>header small{font-weight:400;color:var(--text-muted)}.question-panel textarea{margin:14px;resize:vertical}.question-actions{display:flex;gap:8px;padding:0 14px 12px}.generated-questions{margin:0 14px 14px;border:1px solid var(--border);background:#fff}.generated-head{display:flex;justify-content:space-between;padding:10px 12px;border-bottom:1px solid var(--border)}.generated-head small{color:var(--text-muted)}.generated-list{max-height:min(46vh,460px);overflow-y:auto}.generated-questions article{padding:11px 12px;border-bottom:1px solid #edf2f7}.generated-questions article:last-child{border-bottom:0}.question-number{display:inline-flex;margin-bottom:6px;padding:2px 7px;border-radius:5px;background:#eef2ff;color:#4338ca;font-size:11px;font-weight:600}.generated-questions p{margin:0 0 6px;line-height:1.6}.generated-questions article small{display:block;color:var(-